"""Build two public, prerelease product sites. No installers or package artifacts."""
from pathlib import Path
import html,json,re,shutil,sys
from markdown_it import MarkdownIt
from pygments import highlight
from pygments.lexers import get_lexer_by_name,TextLexer
from pygments.formatters import HtmlFormatter
ROOT=Path(__file__).resolve().parent
REPO=ROOT.parent
REPORTS=REPO.parent/'NextgenReportEngine'
sys.path.insert(0,str(REPO/'scripts'))
from manual_content import D

def escape(s):return html.escape(str(s),quote=True)
def code(s,lang,attrs):
 try:lexer=get_lexer_by_name({'razor':'html','cs':'csharp'}.get(lang,lang))
 except Exception:lexer=TextLexer()
 return '<pre class="highlight"><code>'+highlight(s,lexer,HtmlFormatter(nowrap=True))+'</code></pre>'
md=MarkdownIt('commonmark',{'html':True,'highlight':code}).enable('table')
DATA={
'components':dict(name='Components',mark='Nc',tag='Blazor + Flutter Web',title='Great interfaces.<br><em>One shared language.</em>',description='A growing UI library for Blazor and Flutter Web. Build forms, data workspaces and visual tools with a consistent design system.',detail='From the first input to a complete business workspace. Explore real components, clear state contracts and detailed examples for both frameworks.',hero='components-workspace.png',hero_caption='Nextgen Components · Data workspace',stats=[('47','controls per framework'),('2','Web implementations'),('94','documented examples')],pills=['Blazor','Flutter Web','Light & dark themes'],section='The pieces your next<br>application needs.',features=[('01','Forms that work together','Text, numeric, date and choice editors with validation, responsive sections and controlled state.','NgForm'),('02','Data, without the clutter','Page and search remote records, combine sorting rules, and load tree branches as users explore.','NgDataGrid'),('03','Make your data visible','Charts, gauges, schedules, maps and document tools for richer business workspaces.','NgChart')],shots=[('components-tree.png','A hierarchy that loads as you explore','TreeView and TreeList with lazy children, independent locks and retry.'),('components-charts.png','Visual tools with readable examples','Chart interactions and a shared documentation workspace.')],workflow_title='Two frameworks.<br>Familiar building blocks.',workflow_text='Keep your application in control of data and state. Each component guide explains its parameters, events, examples and current boundaries.',checks=['Typed columns and stable row identities','Parent-owned selection and expansion','Detailed Blazor and Flutter examples'],code='''<span class="comment">// Load exactly the page your user needs.</span>\n<span class="word">NgDataRequest</span> request\n  Page      <span class="val">→ 1</span>\n  PageSize  <span class="val">→ 20</span>\n  Search    <span class="val">→ "Design"</span>\n  Sorts     <span class="val">→ Name ↑, Quantity ↓</span>\n\n<span class="word">NgDataResult&lt;Product&gt;</span>\n  Items     <span class="val">→ current page</span>\n  Total     <span class="val">→ filtered record count</span>''',faq=[('Can I download the library now?','Not yet. This site is a product preview and documentation resource. Leave a preorder request to hear about availability and licensing.'),('Which platforms are verified?','The current verified targets are Blazor Web and Flutter Web. Native desktop and mobile verification remain separate work.'),('Is this a complete Telerik replacement?','No. These are original components with documented implemented subsets. Full Telerik feature, API and visual compatibility is not claimed.'),('What does a preorder request commit me to?','Nothing is charged or reserved. This is a non-binding request for product information; pricing, terms and release dates will be shared separately.')]),
'reports':dict(name='Reports',mark='Nr',tag='Design · Data · Documents',title='Your data.<br><em>Beautifully reported.</em>',description='Design, preview and export paginated reports with a visual Studio, versioned templates and a .NET report engine.',detail='Turn business data into documents people can use. Build reports visually, connect data and parameters, then render through a shared engine.',hero='reports-studio.png',hero_caption='Nextgen Reports · Visual report designer',stats=[('Visual','report authoring'),('.NET','engine & integration'),('6','main export formats')],pills=['Visual Studio','Blazor integration','Flutter viewer'],section='From raw records<br>to a finished report.',features=[('01','Design with context','Arrange text, images, tables, charts and barcodes. Use the report tree, data dictionary and property editor.','report-authoring-manual'),('02','Connect your data','Work with JSON, objects, SQL and HTTP sources. Add filters, groups, calculations and report parameters.','data-sources'),('03','Deliver useful documents','Preview pages and export PDF, HTML, SVG, PNG, Excel or Word using the report engine.','exports')],shots=[('reports-demo.png','A report inside your application','Blazor integration with parameters, preview and export controls.'),('reports-flutter.png','Bring reports to Flutter Web','A viewer for generated report pages, backed by the same HTTP workflow.')],workflow_title='Design once.<br>Render with confidence.',workflow_text='Versioned JSON templates describe your report. Binding and layout run in the engine, so the designer and integrations share the document model.',checks=['Paginated output with repeated headings','Parameters, grouping and cross-tabs','Embedded fonts in PDF output'],code='''<span class="comment">// A report begins with a clear data contract.</span>\n{\n  <span class="word">"version"</span>: <span class="val">1</span>,\n  <span class="word">"blocks"</span>: [{\n    <span class="word">"type"</span>: <span class="val">"text"</span>,\n    <span class="word">"text"</span>: <span class="val">"Hello, {{data.customer}}"</span>\n  }]\n}\n\n<span class="comment">Template → binding → layout → export</span>''',faq=[('Can I install Nextgen Reports from this site?','Not yet. This site presents the product and its documentation. Request preorder information for future availability; there are no public installers or packages here.'),('Does PDF generation require Microsoft Office?','No. The PDF engine uses embedded fonts and does not require Microsoft Office or a browser to render PDF.'),('What do the Excel and Word exports contain?','They support editable displayed text or complete rendered page images. They do not preserve original data types, formulas or native Office charts.'),('Which platforms have been checked?','Local verification includes Linux on iMac, browser workflows and a Linux x64 desktop shell. Windows/macOS packaging and native mobile devices remain unverified.'),('Is a preorder request a purchase?','No. The form records non-binding interest. No payment is collected, and pricing, license terms and release dates are not promised.')])}

def brand(d):return f'<a class="brand" href="/" aria-label="Nextgen {d["name"]} home"><span class="mark">{d["mark"]}</span>Nextgen<span>{d["name"]}</span></a>'
def header(d,doc=False):return f'<header class="{"doc-header" if doc else ""}"><div class="wrap"><div class="topbar">{brand(d)}<nav class="nav" aria-label="Main navigation"><a href="/#features">Features</a><a href="/#screenshots">Screenshots</a><a href="/docs/">Documentation</a><a class="button small" href="/#preorder">Preorder interest <span aria-hidden="true">↗</span></a></nav></div></div></header>'
def footer(d):
 other='reports' if d['name']=='Components' else 'components'
 return f'<footer class="footer"><div class="wrap">{brand(d)}<div><a href="/docs/">Documentation</a><a href="/privacy/">Privacy</a><a href="https://{other}.softwarenextgen.com">Nextgen {other.title()} ↗</a></div><span>© 2026 Nextgen · Product preview</span></div></footer>'
def page(kind,title,body,path='/',doc=False):
 d=DATA[kind];canonical=f'https://{kind}.softwarenextgen.com{path}'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · Nextgen {d['name']}</title><meta name="description" content="{escape(d['description'])}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="Nextgen {d['name']} — {escape(title)}"><meta property="og:description" content="{escape(d['description'])}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://{kind}.softwarenextgen.com/images/{d['hero']}"><meta name="theme-color" content="#0c172b"><link rel="icon" href="/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="/site.css"><link rel="stylesheet" href="/syntax.css"><script src="/site.js" defer></script></head><body class="{kind}"><a class="skip" href="#main">Skip to content</a>{header(d,True) if doc else ''}{body}{footer(d)}</body></html>'''
def form(d):return f'''<section class="section preorder" id="preorder"><div class="wrap preorder-grid"><div><p class="eyebrow"><span class="dot"></span> Be part of what comes next</p><h2>Tell us what<br>you’re building.</h2><p>Interested in Nextgen {d['name']}? Tell us about your project. We’ll get in touch with early access and preorder information.</p><ul class="check-list"><li>No payment required</li><li>No commitment or automatic subscription</li><li>A conversation about your actual needs</li></ul></div><form class="form" id="preorder-form" action="/api/preorder" method="post"><label class="field">Your name<input name="name" autocomplete="name" required maxlength="100" placeholder="Alex Morgan"></label><label class="field">Work email<input name="email" autocomplete="email" type="email" required maxlength="254" placeholder="you@company.com"></label><label class="field">Company <span class="form-note">Optional</span><input name="company" autocomplete="organization" maxlength="160" placeholder="Company or team"></label><label class="field">Primary interest<select name="interest"><option value="{d['name']}">Nextgen {d['name']}</option><option value="Both products">Both Nextgen products</option></select></label><label class="field full">What would you like to build? <span class="form-note">Optional</span><textarea name="message" maxlength="2000" placeholder="Your use case, framework or team requirements…"></textarea></label><label class="trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent full"><input type="checkbox" name="consent" value="yes" required><span>I agree to be contacted about my request and have read the <a href="/privacy/">privacy notice</a>.</span></label><button class="button full" type="submit">Request preorder details →</button><p class="form-note full">This is an expression of interest, not a paid order. Availability and commercial terms will be confirmed separately.</p><div class="form-status full" role="status" aria-live="polite" tabindex="-1"></div><noscript><p class="form-note full">Please enable JavaScript to securely submit this form.</p></noscript></form></div></section>'''
def landing(kind):
 d=DATA[kind]
 cards=''.join(f'<article class="card"><div class="symbol" aria-hidden="true">{n}</div><h3>{title}</h3><p>{copy}</p><a href="/docs/{slug}/">Explore the documentation →</a></article>' for n,title,copy,slug in d['features'])
 shots=''.join(f'<figure class="shot"><a href="/images/{file}" aria-label="View {escape(title)} screenshot"><img src="/images/{file}" alt="{escape(title)}" loading="lazy" width="1440" height="960"></a><figcaption><b>{title}</b><span>{copy}</span></figcaption></figure>' for file,title,copy in d['shots'])
 faq=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in d['faq'])
 body=f'''<div class="hero-shell">{header(d)}<main id="main"><div class="wrap"><div class="hero"><div><p class="eyebrow"><span class="dot"></span> {d['tag']} · Product preview</p><h1>{d['title']}</h1><p class="hero-copy">{d['description']}</p><div class="hero-actions"><a class="button" href="#preorder">Request preorder details →</a><a class="button secondary" href="/docs/">Explore the docs</a></div><p class="hero-note">Explore today. Request access for what comes next.</p></div><div class="hero-side"><p>{d['detail']}</p><div class="signal">{''.join(f'<div><strong>{v}</strong><span>{l}</span></div>' for v,l in d['stats'])}</div><div class="pill-row">{''.join(f'<span class="pill">{p}</span>' for p in d['pills'])}</div></div></div><div class="preview"><div class="preview-bar"><i></i><i></i><i></i><span>{d['hero_caption']}</span></div><img src="/images/{d['hero']}" alt="{d['hero_caption']}, actual application screenshot" width="1440" height="960" fetchpriority="high"></div></div></main></div><section class="section" id="features"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Built for real workflows</p><h2>{d['section']}</h2></div><p>Explore what is implemented today, with clear examples and honest boundaries. Every feature has a place in the documentation.</p></div><div class="cards">{cards}</div></div></section><section class="section tint" id="screenshots"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Inside the product</p><h2>A closer look.</h2></div><p>Real application screens with sample data. See how the tools fit into a working development workflow.</p></div><div class="showcase">{shots}</div></div></section><section class="section"><div class="wrap workflow"><div><p class="eyebrow">Built for developers</p><h2>{d['workflow_title']}</h2><p>{d['workflow_text']}</p><ul class="check-list">{''.join(f'<li>{x}</li>' for x in d['checks'])}</ul><a class="button light" href="/docs/">Read the documentation →</a></div><div class="code-panel" aria-label="Illustrative data contract">{d['code']}</div></div></section>{form(d)}<section class="section"><div class="wrap faqs"><p class="eyebrow">Before you ask</p><h2>A few useful answers.</h2>{faq}</div></section>'''
 return page(kind,'Build what comes next',body)

def clean_component(source):
 source=re.sub(r'\[Manual\].*?\n','',source,count=1)
 source=re.sub(r'## Appearance and live example\n.*?(?=\n## )','',source,flags=re.S)
 return source

def build_docs(kind,out):
 docs={};groups={}
 if kind=='components':
  catalog=json.loads((REPO/'docs/catalog.json').read_text())['components'];categories={}
  for item in catalog:
   name=item['blazor']['component']
   if name:categories[name]=item['category']
  for name,details in D.items():
   docs[name]=(details['title'],md.render(clean_component((REPO/f'docs/manual/{name}.md').read_text())))
   groups.setdefault(categories.get(name,'Components'),[]).append(name)
  overview='''# Nextgen Components documentation\n\nExplore the current Blazor and Flutter Web library: 47 components, shared design tokens and practical examples.\n\n> This is prerelease documentation. Public packages and installers are not available from this site. Use the preorder form to request availability information.\n\n## Start with a workflow\n\n- **Forms:** inputs, validation, responsive sections and date editors.\n- **Data:** remote Grid paging, search and multi-sort; lazy TreeView and TreeList branches.\n- **Visualization:** charts, gauges, schedules, maps and document tools.\n\n## Read a component guide\n\nEach guide explains state ownership, parameters, events, current behavior and examples for both frameworks. Code examples describe the implemented API; they are not a public package installation flow.\n\n## Current boundaries\n\nThe verified targets are Blazor Web and Flutter Web. Native/mobile and full screen-reader verification remain open. These original implementations do not claim complete Telerik feature or API parity. Grid virtualization/grouping/CRUD and tree drag-and-drop/checkbox selection are still planned.\n'''
 else:
  selected={'report-authoring-manual':'Visual report authoring','template-format':'Template reference','data-sources':'Data connections','data-import':'CSV and Excel import','data-preparation':'Data preparation','report-logic-manual':'Logic and events','drill-down':'Drill-down reports','report-library':'Library and versions','office-export':'Excel and Word export','image-export':'Image export'}
  for slug,title in selected.items():
   source=(REPORTS/f'docs/{slug}.md').read_text()
   if slug=='report-authoring-manual':
    source=re.sub(r'<a href="http://127[^>]+>.*?</a>','',source)
    source=re.sub(r'<p>If Studio is already open.*?</pre>','<p>This guide describes the current Studio workflow. Public installation is not available from this site.</p>',source,flags=re.S)
    source=re.sub(r'<p><a id="download-equipment".*?</p>','<p>The exercise below uses fictional equipment data. Build the example by following the steps.</p>',source,flags=re.S)
   source=re.sub(r'<pre>[^<]*(?:dotnet run|npm |export |python3 |bash )[^<]*</pre>','',source,flags=re.S)
   source=re.sub(r'<li>Start Studio, then run.*?</li>','<li>In the Blazor integration, change parameters and apply data to generate a new preview.</li>',source,flags=re.S)
   source=re.sub(r'```(?:sh|bash|shell|powershell)\n.*?```','',source,flags=re.S)
   source=re.sub(r'(?m)^.*(?:/home/kolizej|npm ci|dotnet add|flutter pub get|pip install).*$','',source)
   docs[slug]=(title,md.render(source))
  groups={'Authoring':['report-authoring-manual','template-format','report-logic-manual'],'Data':['data-sources','data-import','data-preparation','drill-down'],'Documents':['exports','office-export','image-export','report-library']}
  docs['exports']=('Preview and export',md.render('''# Preview and export\n\nNextgen Reports separates report layout from document export. Preview calculated pages, then choose the format that fits the recipient.\n\n| Format | Current behavior |\n| --- | --- |\n| PDF | Paginated document with embedded fonts; no Office or browser dependency for PDF rendering. |\n| HTML | Standalone SVG pages with embedded assets. |\n| SVG / PNG | Page or page-range export; PNG supports configurable DPI. |\n| Excel / Word | Editable displayed text or complete rendered page images. Original types, formulas and native Office charts are not preserved. |\n\n## A reliable workflow\n\n1. Select report parameters and generate preview.\n2. Check page breaks, repeated table headings, totals and footers.\n3. Select the appropriate output format and range.\n4. Verify the resulting document in its target viewer.\n\nThese are product capabilities. This public site does not offer report downloads, installers or packages.\n'''))
  overview='''# Nextgen Reports documentation\n\nDesign reports visually, bind business data and produce paginated documents through a shared .NET engine.\n\n> This is prerelease documentation. No installers or packages are distributed here. Request preorder information for future availability.\n\n## Follow the report workflow\n\n1. **Design:** arrange text, images, tables, charts and barcodes in Studio.\n2. **Connect:** bind JSON, objects, SQL or HTTP data; add parameters and calculations.\n3. **Preview:** inspect calculated pages, repeated headings and totals.\n4. **Deliver:** export PDF, HTML, SVG, PNG, Excel or Word.\n\n## Shared document architecture\n\n`ReportTemplate → binding → layout → ReportDocument → exporter`\n\nTemplates use versioned JSON. Studio, Blazor integration and Flutter viewers share the report protocol rather than implementing separate page layout engines.\n\n## Current boundaries\n\nLinux local workflows are verified; Windows/macOS packaging and native mobile devices are unverified. Excel/Word exports preserve displayed text or page images, not source formulas or native Office charts. External subreports, SSO and per-report ACL remain planned.\n'''
 docs['index']=('Overview',md.render(overview))
 def fix_links(body):
  def replace(m):
   label=m.group(2);href=html.unescape(m.group(1));slug=Path(href.split('#')[0]).stem
   if href.startswith('#'):return m.group(0)
   if slug in docs:return f'<a href="/docs/{slug}/">{label}</a>'
   if href.startswith('https://') and 'github.com' not in href:return m.group(0)
   return label
  return re.sub(r'<a[^>]*href="([^"]+)"[^>]*>(.*?)</a>',replace,body,flags=re.S)
 for slug,(title,body) in docs.items():
  links='<a href="/docs/" data-search="overview introduction" '+('aria-current="page"' if slug=='index' else '')+'>Overview</a>'
  for group,items in groups.items():
   entries=''.join(f'<a href="/docs/{n}/" data-search="{escape((n+" "+docs[n][0]+" "+group).lower())}" '+('aria-current="page"' if n==slug else '')+f'>{escape(docs[n][0])}</a>' for n in sorted(items))
   links+=f'<details open><summary>{escape(group)}</summary>{entries}</details>'
  sidebar=f'<aside class="sidebar" aria-label="Documentation navigation"><label for="doc-search">Find a guide</label><input id="doc-search" type="search" placeholder="Search documentation…">{links}<p class="no-results" hidden>No matching guides.</p></aside>'
  body=fix_links(body)
  # Generate stable heading anchors for Markdown pages; authored HTML anchors remain intact.
  body=re.sub(r'<h([23])>(.*?)</h\1>',lambda m:f'<h{m[1]} id="{re.sub(r"[^a-z0-9 -]","",re.sub(r"<[^>]+>","",m[2]).lower()).replace(" ","-")}">{m[2]}</h{m[1]}>',body)
  path='/docs/' if slug=='index' else f'/docs/{slug}/'
  article=f'<button class="mobile-docs button light" aria-expanded="true">Browse documentation</button><div class="docs-layout">{sidebar}<main id="main" class="doc-content"><div class="breadcrumbs"><a href="/">Nextgen {DATA[kind]["name"]}</a> / Documentation / {escape(title)}</div><p class="section-label">Product documentation</p>{body}<div class="reading-footer">Current implementation · Product preview<br><a href="/#preorder">Request preorder information →</a></div></main></div>'
  target=out/path.strip('/');target.mkdir(parents=True,exist_ok=True);(target/'index.html').write_text(page(kind,title,article,path,True))
 return len(docs)

def build(kind):
 out=ROOT/'dist'/kind;out.mkdir(parents=True,exist_ok=True)
 for name in ['site.css','site.js']:shutil.copyfile(ROOT/'shared'/name,out/name)
 (out/'syntax.css').write_text(HtmlFormatter(style='github-dark').get_style_defs('.highlight'))
 (out/'images').mkdir(exist_ok=True)
 for file in (ROOT/'screenshots').glob(f'{kind}-*.png'):shutil.copyfile(file,out/'images'/file.name)
 d=DATA[kind];(out/'icon.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#635be8"/><text x="32" y="42" fill="white" text-anchor="middle" font-size="30" font-family="sans-serif" font-weight="700">{d["mark"]}</text></svg>')
 (out/'index.html').write_text(landing(kind));count=build_docs(kind,out)
 privacy='''<main id="main" class="wrap doc-content"><h1>Privacy notice</h1><p>Last updated: 19 October 2026.</p><h2>What the preorder form collects</h2><p>We collect your name, email address, optional company, product interest and optional message to respond to your request about Nextgen products. A request is not a purchase or a marketing subscription.</p><h2>How requests are handled</h2><p>Your submission is stored in a private Cloudflare database and forwarded to the product team’s private inbox. Cloudflare processes the site and form; the team’s email provider processes notification messages. The receiving address is not published on this site.</p><h2>Security and retention</h2><p>The form uses a short-lived security cookie, request validation and abuse controls. A limited, hashed network identifier may be used to prevent repeated spam; it is not used for advertising. Please do not submit passwords, financial information or sensitive personal data. Requests are retained while we respond and discuss availability, for up to 12 months unless an ongoing relationship requires otherwise.</p><h2>Your choices</h2><p>You can request correction, deletion or no further contact by replying to our response, or by submitting this form again with your request. We do not sell your contact details. This site does not use advertising trackers or optional analytics cookies.</p><a class="button light" href="/#preorder">Back to the request form</a></main>'''
 (out/'privacy').mkdir(exist_ok=True);(out/'privacy/index.html').write_text(page(kind,'Privacy notice',privacy,'/privacy/',True))
 (out/'404.html').write_text(page(kind,'Page not found','<main id="main" class="wrap section"><h1>That page is not here.</h1><p>Explore the product documentation or return to the homepage.</p><a class="button" href="/docs/">Browse documentation</a></main>','/404',True))
 urls=['https://'+kind+'.softwarenextgen.com/'+str(f.parent.relative_to(out)).replace('.','').strip('/')+'/' for f in out.rglob('index.html')]
 urls=[u.replace('.com//','.com/') for u in urls]
 (out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{u}</loc></url>' for u in urls)+'</urlset>')
 (out/'robots.txt').write_text(f'User-agent: *\nAllow: /\nDisallow: /api/\nSitemap: https://{kind}.softwarenextgen.com/sitemap.xml\n')
 print(f'{kind}: {count} documentation pages, landing, privacy, screenshots')
for kind in DATA:build(kind)
